/**
 * The app icons are the mark (the Icons and Panels artboards), regenerated by
 * `tools/make-icons.mjs` from `ui/src/logoCells.ts` and the accent token.
 *
 * Pinned: the committed files are exactly what the script renders today, so an
 * edit to the mark that forgot `npm run icons` fails here rather than shipping
 * an old icon; and at 24 px and below the ghost squares are left out, which is
 * the one rule that makes the taskbar icon crisp.
 */

import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

import sharp from 'sharp';
import { describe, expect, it } from 'vitest';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');

interface IconTool {
  renderIcons: () => Promise<Map<string, Buffer>>;
  ICO_SIZES: number[];
}

const tool = (await import(pathToFileURL(path.join(ROOT, 'tools', 'make-icons.mjs')).href)) as IconTool;

/** Each image in an .ico, by size. */
function icoImages(ico: Buffer): Map<number, Buffer> {
  const images = new Map<number, Buffer>();
  for (let i = 0; i < ico.readUInt16LE(4); i += 1) {
    const at = 6 + 16 * i;
    const length = ico.readUInt32LE(at + 8);
    const offset = ico.readUInt32LE(at + 12);
    images.set(ico[at] || 256, ico.subarray(offset, offset + length));
  }
  return images;
}

/** The pixel at a point given in the mark's 24-unit box, for an icon whose mark is `markFraction` of it. */
async function pixelAt(png: Buffer, size: number, markFraction: number, unitX: number, unitY: number) {
  const mark = size * markFraction;
  const offset = (size - mark) / 2;
  const x = Math.floor(offset + (unitX * mark) / 24);
  const y = Math.floor(offset + (unitY * mark) / 24);
  const { data, info } = await sharp(png).raw().toBuffer({ resolveWithObject: true });
  const at = (y * info.width + x) * info.channels;
  return [data[at], data[at + 1], data[at + 2]] as const;
}

describe('the app icons', () => {
  it('are exactly what tools/make-icons.mjs renders from the mark', async () => {
    const rendered = await tool.renderIcons();
    expect([...rendered.keys()].sort()).toEqual([
      'cleaner/installer/icon.png',
      'master/installer/icon.ico',
      'master/installer/icon.png',
      'office/installer/icon.ico',
      'office/installer/icon.png',
    ]);
    for (const [file, data] of rendered) {
      expect(readFileSync(path.join(ROOT, file)).equals(data), `${file} is stale: run npm run icons`).toBe(true);
    }
  }, 60_000);

  it('draw every Windows size on its own, and leave the ghosts out at 24 px and below', async () => {
    const images = icoImages(readFileSync(path.join(ROOT, 'office', 'installer', 'icon.ico')));
    expect([...images.keys()]).toEqual(tool.ICO_SIZES);

    // The Office tile is cobalt with a white mark: a ghost square is white at
    // 30 % over cobalt, an empty spot is the cobalt itself. Centre of the first
    // ghost square (13, 4)-(17, 8) and of an inked one (1, 4)-(5, 8).
    const MARK = { 16: 14 / 16, 24: 20 / 24, 32: 26 / 32, 256: 168 / 240 } as const;
    for (const size of [16, 24, 32, 256] as const) {
      const png = images.get(size) as Buffer;
      const [, , blueAtGhost] = await pixelAt(png, size, MARK[size], 15, 6);
      const [redAtGhost] = await pixelAt(png, size, MARK[size], 15, 6);
      const [redAtInk] = await pixelAt(png, size, MARK[size], 3, 6);
      expect(redAtInk, `${size} px inked square is white`).toBeGreaterThan(230);
      expect(blueAtGhost, `${size} px tile`).toBeGreaterThan(120);
      if (size <= 24) {
        expect(redAtGhost, `${size} px: no ghost, the tile shows through`).toBeLessThan(40);
      } else {
        expect(redAtGhost, `${size} px: a ghost, white at 30 % over cobalt`).toBeGreaterThan(70);
        expect(redAtGhost).toBeLessThan(160);
      }
    }
  }, 60_000);
});
